/// <summary>
/// PaffH 17.08.22
/// </summary>
/// <param name = "_NDXProdIdentProcedureLine1">RefRecId to NDXProdIdentProcedureLine1</param>
/// <param name = "_idSort">NDXIDSort</param>
/// <param name = "_subId">NDXIDSortSubProdIdentBlock</param>
/// <param name = "_NDXProdIdentBlockTable">RefRecId to NDXProdIdentBlockTable</param>
/// <param name = "_blockFieldName">NDXProdIdentBlockFieldName</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentBlock2ItemId</returns>
public static NDXProdIdentBlock2ItemId find(
    RefRecId _NDXProdIdentProcedureLine1,
    NDXIDSort _idSort, 
    NDXIDSortSubProdIdentBlock _subId, 
    RefRecId _NDXProdIdentBlockTable,
    NDXProdIdentBlockFieldName _blockFieldName,
    boolean _forUpdate = true)
{
    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemId;
    nDXProdIdentBlock2ItemId.selectForUpdate(_forUpdate);
    select firstonly nDXProdIdentBlock2ItemId
        where nDXProdIdentBlock2ItemId.NDXProdIdentProcedureLine1 == _NDXProdIdentProcedureLine1
        && nDXProdIdentBlock2ItemId.IDSort == _idSort
        && nDXProdIdentBlock2ItemId.SubId == _subId
        && nDXProdIdentBlock2ItemId.NDXProdIdentBlockTable == _NDXProdIdentBlockTable
        && nDXProdIdentBlock2ItemId.BlockIdFieldName == _blockFieldName;

    return nDXProdIdentBlock2ItemId;
}

/// <summary>
/// PaffH 17.08.22
/// </summary>
/// <param name = "_NDXProdIdentProcedureLine1">RefRecId</param>
/// <param name = "_idSort">NDXIDSort</param>
/// <param name = "_subId">NDXIDSortSubProdIdentBlock</param>
/// <param name = "_NDXProdIdentBlockTable">RefRecId</param>
/// <param name = "_blockFieldName">NDXProdIdentBlockFieldName</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXProdIdentBlock2ItemId</returns>
public static NDXProdIdentBlock2ItemId findOrCreate(
    RefRecId _NDXProdIdentProcedureLine1,
    NDXIDSort _idSort,
    NDXIDSortSubProdIdentBlock _subId,
    RefRecId _NDXProdIdentBlockTable,
    NDXProdIdentBlockFieldName _blockFieldName,
    boolean _doInsert = true)
{
    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemId;
    nDXProdIdentBlock2ItemId = NDXProdIdentBlock2ItemId::find(
        _NDXProdIdentProcedureLine1,
        _idSort,
        _subId,
        _NDXProdIdentBlockTable,
        _blockFieldName,
        true);
    if (!nDXProdIdentBlock2ItemId)
    {
        nDXProdIdentBlock2ItemId.NDXProdIdentProcedureLine1 = _NDXProdIdentProcedureLine1;
        nDXProdIdentBlock2ItemId.IDSort = _idSort;
        nDXProdIdentBlock2ItemId.SubId = _subId;
        nDXProdIdentBlock2ItemId.NDXProdIdentBlockTable = _NDXProdIdentBlockTable;
        nDXProdIdentBlock2ItemId.BlockIdFieldName = _blockFieldName;

        if (_doInsert)
        {
            nDXProdIdentBlock2ItemId.insert();
        }
    }

    return nDXProdIdentBlock2ItemId;
}

/// <summary>
/// PaffH 14.03.23
/// AX2009: tables.NDX_ProdIdent_Block2ItemId.checkElements4ItemId()
/// populate missing BlockIds
/// </summary>
/// <param name = "_nDXProdIdentProcedureLine2">NDXProdIdentProcedureLine2</param>
static void checkElements4ItemId(NDXProdIdentProcedureLine2 _nDXProdIdentProcedureLine2)
{
    NDXProdIdentBlockTable        lNDX_ProdIdent_BlockTable;
    NDXProdIdentBlock2ItemId      lnDXProdIdentBlock2ItemId;

    Set set1 = new Set(Types::String);
    Set set2 = new Set(Types::String);
    Set set3 = new Set(Types::String);
    SetEnumerator   enum;
    NDXProdIdentBlockId   blockId;

    ;
    while select lNDX_ProdIdent_BlockTable
    {
        set1.add(lNDX_ProdIdent_BlockTable.Id);
    }
    while select lnDXProdIdentBlock2ItemId
        where  lnDXProdIdentBlock2ItemId.NDXProdIdentProcedureLine1 == _nDXProdIdentProcedureLine2.NDXProdIdentProcedureLine1
            && lnDXProdIdentBlock2ItemId.IDSort == _nDXProdIdentProcedureLine2.IDSort
    {
        set2.add(NDXProdIdentBlockTable::findRecId(lnDXProdIdentBlock2ItemId.NDXProdIdentBlockTable).ID);
    }
    set3 = Set::difference(set1, set2);
    enum = set3.getEnumerator();

    RecordInsertList nDXProdIdentBlock2ItemIdList = new RecordInsertList(tableNum(NDXProdIdentBlock2ItemId));
    while (enum.moveNext())
    {
        blockId = enum.current();
        lnDXProdIdentBlock2ItemId.clear();
        lnDXProdIdentBlock2ItemId.NDXProdIdentProcedureLine1 = _nDXProdIdentProcedureLine2.NDXProdIdentProcedureLine1;
        lnDXProdIdentBlock2ItemId.IDSort = _nDXProdIdentProcedureLine2.IDSort;
        lnDXProdIdentBlock2ItemId.NDXProdIdentBlockTable = NDXProdIdentBlockTable::find(blockId).RecId;
        nDXProdIdentBlock2ItemIdList.add(lnDXProdIdentBlock2ItemId);
    }
    nDXProdIdentBlock2ItemIdList.insertDatabase();
}

/// <summary>
/// PaffH 03.01.25
/// </summary>
/// <returns>NDXProdIdentBlockTable</returns>
public NDXProdIdentBlockTable parmNDXProdIdentBlockTable()
{
    NDXProdIdentBlockTable nDXProdIdentBlockTable = NDXProdIdentBlockTable::findRecId(this.NDXProdIdentBlockTable);
    return nDXProdIdentBlockTable;
}

/// <summary>
/// PaffH 02.01.25
/// AX2009: tables.NDX_ProdIdent_Block2ItemId.getDataFromBlockType()
/// </summary>
/// <param name = "blockType">NDXProdIdentBlockType</param>
/// <param name = "lNDX_ProdIdent_ProcedureLine2">NDXProdIdentProcedureLine2</param>
/// <returns></returns>
static container getDataFromBlockType(NDXProdIdentBlockType blockType, NDXProdIdentProcedureLine2 lNDXProdIdentProcedureLine2)
{
    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemId;

    container conData = connull();

    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds1, qbds2;

    int                     i;
    NDXProdIdentBlockId   blockId;

    container conBlockIds = NDXProdIdentBlockTable::getDataFromBlockType(blockType);
    if (!conBlockIds)
    {
        return conData;
    }

    q = new Query();

    //QueryBuildDataSource qbdsNDXProdIdentBlock2ItemId = q.addDataSource(tablenum(NDXProdIdentBlock2ItemId));
    //QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = qbdsNDXProdIdentBlock2ItemId.addDataSource(tablenum(NDXProdIdentProcedureLine2));
    //qbdsNDXProdIdentProcedureLine2.joinMode(JoinMode::InnerJoin);
    //qbdsNDXProdIdentProcedureLine2.fetchMode(QueryFetchMode::One2One);
    //qbdsNDXProdIdentProcedureLine2.relations(true);

    QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = q.addDataSource(tablenum(NDXProdIdentProcedureLine2));
    qbdsNDXProdIdentProcedureLine2.addRange(fieldnum(NDXProdIdentProcedureLine2, RecId)).value(QueryValue(lNDXProdIdentProcedureLine2.RecId));

    QueryBuildDataSource qbdsNDXProdIdentBlock2ItemId = qbdsNDXProdIdentProcedureLine2.addDataSource(tablenum(NDXProdIdentBlock2ItemId));
    qbdsNDXProdIdentBlock2ItemId.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentBlock2ItemId.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentBlock2ItemId.relations(true);
    // Sortierung
    qbdsNDXProdIdentBlock2ItemId.addSortField(fieldnum(NDXProdIdentBlock2ItemId, IDSort));

    QueryBuildDataSource qbdsNDXProdIdentBlockTable = qbdsNDXProdIdentBlock2ItemId.addDataSource(tableNum(NDXProdIdentBlockTable));
    qbdsNDXProdIdentBlockTable.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentBlockTable.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentBlockTable.relations(true);
    qbdsNDXProdIdentBlockTable.addSortField(fieldnum(NDXProdIdentBlockTable, Id));

    // Filter auf Block-ID
    for (i=1; i<=conlen(conBlockIds); ++i)
    {
        blockId = conpeek(conBlockIds, i);
        qbdsNDXProdIdentBlockTable.addRange(fieldnum(NDXProdIdentBlockTable, Id)).value(blockId);
    }
    str infoq2 = q.getSQLStatement();
    qr = new QueryRun(q);
    while (qr.next())
    {
        nDXProdIdentBlock2ItemId = qr.get(tablenum(nDXProdIdentBlock2ItemId));
        if (nDXProdIdentBlock2ItemId.BlockIdFieldName)
        {
            conData += nDXProdIdentBlock2ItemId.BlockIdFieldName;
        }
    }

    return conData;
}
